shell_commands:
node -e "
import('node:fs').then(fs => {
  for (const name of ['test-imports-its-subject', 'require-colocated-tests', 'require-spec-link', 'max-expects']) {
    const candidates = [
      'node_modules/@re-cinq/eslint-plugin-re-lint/rules/' + name + '.js',
      'node_modules/@re-cinq/eslint-plugin-re-lint/dist/rules/' + name + '.js',
      'node_modules/@re-cinq/eslint-plugin-re-lint/src/rules/' + name + '.js',
    ];
    for (const p of candidates) {
      if (fs.existsSync(p)) console.log('=== ' + p + ' ===\n' + fs.readFileSync(p, 'utf8'));
    }
  }
  console.log('pkg:', fs.readdirSync('node_modules/@re-cinq/eslint-plugin-re-lint'));
});
"

node -e "
import('node:fs').then(fs => {
  const pkgDir = 'node_modules/@re-cinq/eslint-plugin-re-lint';
  const walk = d => fs.readdirSync(d, {withFileTypes: true}).flatMap(e => e.isDirectory() ? walk(d + '/' + e.name) : [d + '/' + e.name]);
  const files = walk(pkgDir);
  console.log(files.join('\n'));
  for (const f of files.filter(x => /colocated|subject|spec-link|max-expects/.exec(x))) {
    console.log('=== ' + f + ' ===\n' + fs.readFileSync(f, 'utf8'));
  }
});
"
